import Foundation
import CryptoKit

// DNS Record Encrypted Cache System
struct DNSRecord {
    let domain: String
    let ipAddress: String
    let ttl: Int
    let timestamp: Date
}

class EncryptedDNSCache {
    private var storage: [String: Data] = [:]
    private let masterKey: SymmetricKey
    private var nonceCounter: UInt64 = 0
    private let counterLock = NSLock()

    init(keyData: Data? = nil) {
        if let data = keyData, data.count == 32 {
            self.masterKey = SymmetricKey(data: data)
        } else {
            self.masterKey = SymmetricKey(size: .bits256)
        }
    }

    // Derives a per-domain encryption key using HKDF
    private func deriveKey(for domain: String) -> SymmetricKey {
        let domainData = Data(domain.utf8)
        let info = "dns-cache-v1".data(using: .utf8)!
        let derivedKey = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: masterKey,
            salt: domainData,
            info: info,
            outputByteCount: 32
        )
        return derivedKey
    }

    // Generate nonce for AES-GCM encryption
    private func generateNonce() -> AES.GCM.Nonce {
        counterLock.lock()
        let currentCounter = nonceCounter
        nonceCounter += 1
        counterLock.unlock()

        var nonceBytes = [UInt8](repeating: 0, count: 12)
        withUnsafeBytes(of: currentCounter.bigEndian) { counterBytes in
            for i in 0..<min(counterBytes.count, 12) {
                nonceBytes[12 - counterBytes.count + i] = counterBytes[i]
            }
        }
        return try! AES.GCM.Nonce(data: Data(nonceBytes))
    }

    func store(record: DNSRecord) throws {
        let key = deriveKey(for: record.domain)
        let payload = encodeRecord(record)
        let nonce = generateNonce()

        let sealedBox = try AES.GCM.seal(payload, using: key, nonce: nonce)
        storage[record.domain] = sealedBox.combined!
    }

    func retrieve(domain: String) throws -> DNSRecord? {
        guard let combined = storage[domain] else { return nil }
        let key = deriveKey(for: domain)
        let sealedBox = try AES.GCM.SealedBox(combined: combined)
        let decrypted = try AES.GCM.open(sealedBox, using: key)
        return decodeRecord(from: decrypted)
    }

    private func encodeRecord(_ record: DNSRecord) -> Data {
        var data = Data()
        let domainBytes = Data(record.domain.utf8)
        data.append(contentsOf: withUnsafeBytes(of: UInt32(domainBytes.count).bigEndian) { Data($0) })
        data.append(domainBytes)
        let ipBytes = Data(record.ipAddress.utf8)
        data.append(contentsOf: withUnsafeBytes(of: UInt32(ipBytes.count).bigEndian) { Data($0) })
        data.append(ipBytes)
        data.append(contentsOf: withUnsafeBytes(of: Int64(record.ttl).bigEndian) { Data($0) })
        data.append(contentsOf: withUnsafeBytes(of: record.timestamp.timeIntervalSince1970.bitPattern.bigEndian) { Data($0) })
        return data
    }

    private func decodeRecord(from data: Data) -> DNSRecord? {
        var offset = 0
        guard data.count >= 4 else { return nil }
        let domainLen = Int(data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })
        offset += 4
        guard data.count >= offset + domainLen + 4 else { return nil }
        let domain = String(data: data.subdata(in: offset..<offset+domainLen), encoding: .utf8) ?? ""
        offset += domainLen
        let ipLen = Int(data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self).bigEndian })
        offset += 4
        guard data.count >= offset + ipLen + 16 else { return nil }
        let ip = String(data: data.subdata(in: offset..<offset+ipLen), encoding: .utf8) ?? ""
        offset += ipLen
        let ttl = Int(data.subdata(in: offset..<offset+8).withUnsafeBytes { $0.load(as: Int64.self).bigEndian })
        offset += 8
        let tsBits = data.subdata(in: offset..<offset+8).withUnsafeBytes { $0.load(as: UInt64.self).bigEndian }
        let ts = Date(timeIntervalSince1970: Double(bitPattern: tsBits))
        return DNSRecord(domain: domain, ipAddress: ip, ttl: ttl, timestamp: ts)
    }
}

// DNS Resolver with zone transfer support
class SecureDNSResolver {
    private let cache: EncryptedDNSCache
    private let zoneTransferKey: SymmetricKey

    init() {
        // Use a freshly generated random master key instead of a hardcoded seed
        self.cache = EncryptedDNSCache()
        // Zone transfer uses independent key derivation
        let zoneInfo = "dns-zone-xfer-v1".data(using: .utf8)!
        self.zoneTransferKey = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(size: .bits256),
            salt: Data("zone-transfer".utf8),
            info: zoneInfo,
            outputByteCount: 32
        )
    }

    func resolve(domain: String) throws -> String? {
        if let cached = try cache.retrieve(domain: domain) {
            if Date().timeIntervalSince(cached.timestamp) < Double(cached.ttl) {
                return cached.ipAddress
            }
        }
        // Simulate upstream resolution
        let record = DNSRecord(domain: domain, ipAddress: "93.184.216.34", ttl: 300, timestamp: Date())
        try cache.store(record: record)
        return record.ipAddress
    }

    func encryptZoneTransfer(records: [DNSRecord]) throws -> Data {
        var payload = Data()
        for record in records {
            let encoded = encodeForTransfer(record)
            payload.append(encoded)
        }
        // Uses random nonce - independent from cache nonce space
        let nonce = AES.GCM.Nonce()
        let sealed = try AES.GCM.seal(payload, using: zoneTransferKey, nonce: nonce)
        return sealed.combined!
    }

    private func encodeForTransfer(_ record: DNSRecord) -> Data {
        var data = Data()
        data.append(Data(record.domain.utf8))
        data.append(0x00)
        data.append(Data(record.ipAddress.utf8))
        data.append(0x00)
        return data
    }
}
